({
async open(url){const tab=load("tab");if(tab){await tools.mcp__t3_code__preview_navigate({tabId:tab,url});return tab;}const r=await tools.mcp__t3_code__preview_open({url});if(r.isError)throw Error(JSON.stringify(r));store("tab",r.structuredContent.tabId);return r.structuredContent.tabId;},
async resume(tab,id){const h=eval(load("helpers")),w=eval(load("wf"));const raw=await tools.exec_command({cmd:"cat "+h.q("job-search/wttj-documents/"+id+".json"),max_output_tokens:18000});const m=JSON.parse(raw.output);const f=await h.ev(tab,"({text:document.querySelector('[role=dialog]')?.innerText,fields:[...document.querySelectorAll('[role=dialog] input,[role=dialog] textarea,[role=dialog] select')].filter(e=>e.type!=='hidden').map(e=>({id:e.id,type:e.type,required:e.required}))})");if(!f.text)throw Error("No inspected pending form");if(/not accepting applications from your current location|does not support the locations or timezones/i.test(f.text))throw Error("Native location blocker");if(m.answers){if(f.fields.length!==Object.keys(m.answers).length||f.fields.some(x=>!(x.id in m.answers)))throw Error("Custom form changed");for(const[field,value]of Object.entries(m.answers))await h.ev(tab,"(()=>{const e=document.getElementById("+JSON.stringify(field)+");e.focus();Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,"+JSON.stringify(value)+");e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));e.blur();return e.value})()");await h.save("job-search/applications/"+id+"/answers.json",m.answers);await h.save("job-search/applications/"+id+"/final-form-state-connected.json",await h.inspect(tab));await h.ev(tab,"(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.innerText==='Send application');if(!b||b.disabled)throw Error('Send unavailable');b.click();return true})()");}else{if(f.fields.length!==1||f.fields[0].type!=='textarea'||f.fields[0].required)throw Error("Form changed");await eval(load("campaign")).send(tab,id,m.message);}for(let n=0;n<4;n++){await new Promise(r=>setTimeout(r,1600));if(await w.recordReceipt(tab,id)){await eval(load("one")).close(tab);return true;}}throw Error("Unconfirmed, inspect before retry");},
async review(id,notes){const h=eval(load("helpers"));const r=await tools.exec_command({cmd:"python3 -c "+h.q("import json;from pathlib import Path;p=Path('job-search/applications/"+id+"/verification.json');d=json.loads(p.read_text());assert not d['submitted'];d.update(agent_fact_review=True,visual_review_pending=False,agent_review_notes="+JSON.stringify(notes)+");p.write_text(json.dumps(d,indent=2)+'\\n')"),max_output_tokens:150});if(r.exit_code!==0)throw Error(r.output);},
async finish(id){const tab=load("tab");const r=await eval(load("one")).finish(tab,id);text(r);if(r===true)await eval(load("one")).close(tab);return r;}
})
